'use strict';
let shopGrouping='aisle',shopStoreFilter='all',dayMealDraft=null;
function dayAdviceMarkup(){const theme=dayTheme(selectedDate,state);return `<section class="day-advice"><div><span class="eyebrow">GỢI Ý CHO ${esc(dayName(selectedDate).toLocaleUpperCase('vi'))}</span><h3>${esc(theme.title)}</h3><p>${esc(theme.description)}</p></div><div class="toolbar"><button class="btn soft" data-planning="suggest-day">Gợi ý bữa hôm nay ↗</button><button class="text-btn" data-planning="weekly-advice">Xem cả tuần</button></div></section>`}
function weeklyAdvice(){modal('Một tuần ăn thế nào cho đỡ nghĩ?',`<p class="hint">Đây là gợi ý cách sắp xếp công việc và đổi món, không phải thực đơn dinh dưỡng cá nhân. Bạn chọn số món, khẩu phần, ngân sách và nguyên liệu cần tránh trong Cài đặt.</p><form id="day-themes-form">${Array.from({length:7},(_,i)=>{const date=addDays(weekStart,i),weekday=parseDate(date).getDay(),theme=dayTheme(date,state);return `<div class="day-theme-row"><div><b>${dayName(date)}</b><small>${dateLabel(date)}</small></div><div class="field"><label for="theme-${weekday}">Ưu tiên</label><select id="theme-${weekday}" name="theme-${weekday}">${Object.entries(DAY_THEMES).map(([key,t])=>`<option value="${key}" ${theme.id===key?'selected':''}>${esc(t.title)}</option>`).join('')}</select><small>${esc(theme.description)}</small></div></div>`}).join('')}</form><div class="callout">Các bữa nên đổi nhóm nguyên liệu, có món rau phù hợp và lượng vừa sức ăn. Hai món cùng nhóm sẽ chia phần tự động; cỡ riêng từng món luôn chỉnh được. Gợi ý không tự thay bữa đã khóa hoặc đã nấu.</div>`,`<button class="btn" data-action="settings">Số món / khẩu phần</button><button class="btn primary" data-action="submit-form" data-id="day-themes-form">Lưu ưu tiên từng ngày</button>`,true)}
function suggestedDayMeal(type='dinner'){const meal=clone(currentMeal(type));if(meal.cooked||meal.locked){toast('Bữa đã nấu hoặc khóa được giữ nguyên. Chọn bữa khác hoặc mở khóa trước.',true);return}const other=createMeal(state);other.locked=true;const week={days:{[selectedDate]:{lunch:type==='lunch'?meal:other,dinner:type==='dinner'?meal:other}}};generateWeek(state,week);dayMealDraft={date:selectedDate,type,meal};modal('Gợi ý '+(type==='lunch'?'bữa trưa':'bữa tối'),`<div class="callout">${esc(dayTheme(selectedDate,state).title)} · ${dateLabel(selectedDate)} · ${meal.recipes.length} món · ${+mealServings(meal,state).toFixed(2)} suất chuẩn</div><div class="toolbar">${state.preferences.lunch?'<button class="btn small" data-planning="suggest-lunch">Gợi ý bữa trưa</button>':''}<button class="btn small" data-planning="suggest-dinner">Gợi ý bữa tối</button></div>${meal.recipes.map(r=>`<div class="shop-row"><span class="item-label"><b>${esc(r.name)}</b><small>${CATEGORY[r.category]} · ${r.time} phút · ${dishFactorLabel(meal,r)}</small></span><span class="pill">${aud(mealRecipeCost(meal,r,state))}</span></div>`).join('')}<p class="hint topspace">Ưu tiên ${state.preferences.avoid?'tránh '+esc(state.preferences.avoid):'nguyên liệu hợp với cài đặt'}, thời gian nấu và đồ có trong tủ. Hãy xem công thức và kiểm tra thành phần trước khi áp dụng.</p>`,`<button class="btn" data-planning="suggest-again">Gợi ý khác</button><button class="btn primary" data-planning="apply-day">Áp dụng riêng bữa này</button>`,true)}
function shoppingStoreTools(){return `<div class="shopping-store-tools"><select class="input" id="shopping-group" aria-label="Gom danh sách đi chợ"><option value="aisle" ${shopGrouping==='aisle'?'selected':''}>Gom theo quầy</option><option value="store" ${shopGrouping==='store'?'selected':''}>Gom theo cửa hàng</option></select><select class="input" id="shopping-store-filter" aria-label="Lọc cửa hàng"><option value="all">Tất cả cửa hàng</option><option value="none" ${shopStoreFilter==='none'?'selected':''}>Chưa chọn cửa hàng</option>${(state.stores||[]).map(s=>`<option value="${s.id}" ${shopStoreFilter===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div>`}
function groupedShoppingRows(rows,start,end){const filtered=rows.filter(r=>{const loc=shoppingStore(state,currentWeek(),start,end,r.id);return shopStoreFilter==='all'||shopStoreFilter==='none'&&!loc.storeId||loc.storeId===shopStoreFilter});if(shopGrouping==='aisle')return Object.entries(GROUPS).map(([key,[emoji,name]])=>({key,emoji,name,items:filtered.filter(r=>r.group===key)}));const groups=new Map();for(const r of filtered){const loc=shoppingStore(state,currentWeek(),start,end,r.id),key=loc.storeId||'unassigned';if(!groups.has(key))groups.set(key,{key,emoji:'🏪',name:loc.store?loc.store.name+(loc.store.address?' · '+loc.store.address:''):'Chưa chọn cửa hàng',items:[]});groups.get(key).items.push(r)}return[...groups.values(),{key:'other',emoji:'🛍️',name:'Đồ mua thêm',items:[]}]}
function filteredShoppingExtras(extras){return extras.filter(e=>shopStoreFilter==='all'||shopStoreFilter==='none'&&!e.storeId||e.storeId===shopStoreFilter)}
function shopItemStoreButton(id,start,end){const loc=shoppingStore(state,currentWeek(),start,end,id);return `<button class="store-pill" data-planning="item-store" data-id="${id}">🏪 ${loc.store?esc(loc.store.name):'Chọn nơi mua'}${loc.store?.address?`<small>${esc(loc.store.address)}</small>`:''}${loc.note?`<small>${esc(loc.note)}</small>`:''}</button>`}
function storesModal(){modal('Cửa hàng & địa điểm mua',`<p class="hint">Thêm cửa hàng hoặc chợ bạn thường đi, kèm địa chỉ chi nhánh. App không tự đoán vị trí và không lấy giá trực tiếp từ cửa hàng.</p>${(state.stores||[]).map(s=>`<div class="shop-row"><span class="item-label"><b>${esc(s.name)}</b><small>${esc(s.address||'Chưa nhập địa chỉ')}</small></span>${mapURL(s)?`<a class="text-btn" href="${esc(mapURL(s))}" target="_blank" rel="noopener">Bản đồ ↗</a>`:''}<button class="btn small" data-planning="edit-store" data-id="${s.id}">Sửa</button></div>`).join('')||'<div class="empty">Chưa có cửa hàng. Thêm chi nhánh hoặc chợ nhà mình hay mua.</div>'}`,`<button class="btn primary" data-planning="add-store">+ Thêm cửa hàng</button>`)}
let storeAfterAdd=null;
function storeForm(id){const store=getShop(state,id);modal(store?'Sửa cửa hàng':'Thêm nơi mua đồ',`<form id="store-form-custom" data-id="${store?.id||''}"><div class="field"><label for="store-name">Tên cửa hàng / chợ</label><input id="store-name" name="name" required maxlength="100" value="${esc(store?.name||'')}" placeholder="Ví dụ: Coles, Woolworths, chợ Việt…"></div><div class="field"><label for="store-address">Địa chỉ / chi nhánh (tùy chọn)</label><input id="store-address" name="address" maxlength="300" value="${esc(store?.address||'')}" placeholder="Số nhà, đường, suburb hoặc tên trung tâm"></div><p class="hint">Địa chỉ chỉ do bạn nhập. Nút bản đồ sẽ mở tìm kiếm địa chỉ đó để bạn kiểm tra.</p></form>`,`<button class="btn primary" data-action="submit-form" data-id="store-form-custom">Lưu cửa hàng</button>`)}
function itemStoreModal(id){const[start,end]=shopDates(),loc=shoppingStore(state,currentWeek(),start,end,id);modal('Mua '+INGREDIENTS[id][0]+' ở đâu?',`<form id="item-store-form" data-id="${id}"><div class="field"><label for="item-store">Cửa hàng</label><select id="item-store" name="storeId"><option value="">Chưa chọn / tùy nơi</option>${(state.stores||[]).map(s=>`<option value="${s.id}" ${loc.storeId===s.id?'selected':''}>${esc(s.name)}${s.address?' · '+esc(s.address):''}</option>`).join('')}</select></div><div class="field"><label for="item-store-note">Ghi chú riêng cho lần mua này</label><input id="item-store-note" name="note" maxlength="200" value="${esc(loc.note)}" placeholder="Ví dụ: quầy thịt, lấy bó nhỏ, mua nếu còn tươi…"></div><label class="checked-label"><input class="check" name="remember" type="checkbox" checked> Nhớ nơi mua cho nguyên liệu này</label></form>`,`<button class="btn" data-planning="add-item-store" data-id="${id}">+ Thêm cửa hàng</button><button class="btn primary" data-action="submit-form" data-id="item-store-form">Lưu nơi mua</button>`)}
function shoppingErrandsMarkup(){const rows=(state.errands||[]).filter(r=>r.date>=weekStart&&r.date<=addDays(weekStart,6));if(!rows.length)return'';return `<section class="card shopping-errands"><div class="list-heading"><h2>Nhà nhờ mua thêm</h2><button class="text-btn" data-push-action="request-item">+ Nhờ mua ngay</button></div>${rows.map(r=>{const store=getShop(state,r.storeId);return `<div class="errand-row"><input type="checkbox" class="check" data-planning-change="errand-done" data-id="${r.id}" ${r.done?'checked':''} aria-label="Đã mua ${esc(r.item)}"><div class="${r.done?'done':''}"><b>${esc(r.qty)} ${esc(r.item)}</b><small>Từ ${esc(r.from||'Nhà mình')} · ${r.targets.length?r.targets.map(id=>esc(state.members.find(m=>m.id===id)?.name||'Thành viên')).join(', '):'Cả nhà'} · ${dateLabel(r.date)}</small>${store?`<small>🏪 ${esc(store.name)}${store.address?' · '+esc(store.address):''}</small>`:''}${r.note?`<small>${esc(r.note)}</small>`:''}<small>${r.pushAccepted?'Đã gửi tới dịch vụ push cho '+r.pushAccepted+' thiết bị · chưa xác nhận đã đọc':'Có trong danh sách; chưa xác nhận gửi push'}</small></div><button class="text-btn" data-push-action="resend-request" data-id="${r.id}">Gửi nhắc</button></div>`}).join('')}</section>`}
document.addEventListener('click',event=>{const el=event.target.closest('[data-planning]');if(!el)return;try{switch(el.dataset.planning){case'weekly-advice':weeklyAdvice();break;case'suggest-day':suggestedDayMeal(attendanceType);break;case'suggest-lunch':suggestedDayMeal('lunch');break;case'suggest-dinner':suggestedDayMeal('dinner');break;case'suggest-again':suggestedDayMeal(dayMealDraft?.type||'dinner');break;case'apply-day':{const d=dayMealDraft;if(!d)return;const m=currentWeek().days[d.date][d.type];if(m.locked||m.cooked){toast('Giữ nguyên bữa đã khóa / đã nấu.',true);return}m.recipes=clone(d.meal.recipes);m.tasks={};save('Đã áp dụng gợi ý và cập nhật nguyên liệu.');closeModal();render();break}case'stores':storeAfterAdd=null;storesModal();break;case'add-store':storeForm();break;case'edit-store':storeForm(el.dataset.id);break;case'item-store':itemStoreModal(el.dataset.id);break;case'add-item-store':storeAfterAdd=el.dataset.id;storeForm();break}}catch(error){toast(error.message,true)}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='shopping-group'){shopGrouping=el.value;render()}if(el.id==='shopping-store-filter'){shopStoreFilter=el.value;render()}if(el.dataset.planningChange==='errand-done'){const r=state.errands.find(r=>r.id===el.dataset.id);r.done=el.checked;r.doneAt=el.checked?new Date().toISOString():null;for(const w of Object.values(state.weeks)){const item=w.extras.find(x=>x.errandId===r.id);if(item)item.done=el.checked}save('Đã cập nhật yêu cầu mua thêm.');render()}});
document.addEventListener('submit',event=>{const form=event.target;if(!['day-themes-form','store-form-custom','item-store-form'].includes(form.id))return;event.preventDefault();const d=new FormData(form),v=Object.fromEntries(d);if(form.id==='day-themes-form'){state.preferences.dayThemes=Object.fromEntries(Array.from({length:7},(_,i)=>[i,v['theme-'+i]]));save('Đã nhớ ưu tiên từng ngày.');closeModal();render()}if(form.id==='store-form-custom'){const name=v.name.trim(),address=v.address.trim();if(!name)return;state.stores??=[];let store=state.stores.find(s=>s.id===form.dataset.id);if(store)Object.assign(store,{name,address});else{store={id:uid(),name,address};state.stores.push(store)}save('Đã lưu cửa hàng.');render();if(storeAfterAdd){const id=storeAfterAdd;storeAfterAdd=null;itemStoreModal(id)}else storesModal()}if(form.id==='item-store-form'){const[start,end]=shopDates();setShoppingStore(state,currentWeek(),start,end,form.dataset.id,v.storeId,v.note,d.has('remember'));save('Đã cập nhật nơi mua.');closeModal();render()}});
render();
// Text checklists may contain real-world sale units without a gram conversion.
const applyNotesWithWeights=applyNotes;
applyNotes=function(){if(!notesDraft||notesDraft.target!=='shopping'){applyNotesWithWeights();return}const rows=$$('.note-import-row').filter(el=>$('.note-include',el).checked).map(el=>({raw:notesDraft.rows[+el.dataset.index].raw,match:$('.note-match',el).value,qty:$('.note-qty',el).value===''?null:+$('.note-qty',el).value,unit:$('.note-unit',el).value}));if(!rows.length){toast('Chọn ít nhất một dòng.',true);return}if(rows.some(r=>r.match&&(!(r.qty>0)||!r.unit))){toast('Nhập số lượng và đơn vị cho nguyên liệu đã đối ứng.',true);return}const grouped=new Map();for(const r of rows.filter(r=>r.match)){const list=grouped.get(r.match)||[];list.push(r);grouped.set(r.match,list)}for(const[id,list]of grouped){const units=new Set(list.map(r=>r.unit));if(units.size>1&&!list.every(r=>canonicalQuantity(r.qty,r.unit,id)!==null)){toast('Các dòng cùng nguyên liệu cần cùng đơn vị, hoặc quy về g/kg, ml/lít để gộp.',true);return}}const[start,end]=shopDates(),week=currentWeek(),needed=shopping(state,week,start,end);for(const[id,list]of grouped){const sale=list.some(r=>!['g','kg','ml','l','quả'].includes(r.unit)),amount=list.reduce((n,r)=>n+r.qty,0),unit=list[0].unit,pref=state.purchaseUnitPreferences?.[id];if(sale){const record={unit,amount,basePerUnit:pref?.unit===unit?pref.basePerUnit:null,pricePerUnit:pref?.unit===unit?pref.pricePerUnit:null,note:''};if(needed.some(r=>r.id===id))setBuyingUnits(week,start,end,id,record);else week.extras.push({id:uid(),name:INGREDIENTS[id][0],qty:`${amount} ${unit}`,cost:record.pricePerUnit===null?0:amount*record.pricePerUnit,costUnknown:record.pricePerUnit===null,done:false})}else{const qty=list.reduce((n,r)=>n+canonicalQuantity(r.qty,r.unit,id),0);if(!Number.isFinite(qty)){toast('Đơn vị chưa quy đổi được.',true);return}if(needed.some(r=>r.id===id))setPurchaseQuantity(week,start,end,id,qty);else week.extras.push({id:uid(),name:INGREDIENTS[id][0],qty:fmtQty(qty,INGREDIENTS[id][1]),cost:qty*INGREDIENTS[id][3],done:false})}}for(const r of rows.filter(r=>!r.match))week.extras.push({id:uid(),name:r.raw,qty:r.qty?`${r.qty} ${r.unit}`:'Theo ghi chú',cost:0,costUnknown:true,done:false});log('Nhập '+rows.length+' dòng ghi chú có đơn vị mua');save('Đã nhập danh sách với đúng đơn vị bạn chọn.');closeModal();render()};
